namespace Fanex.Age.UI.Components
{
    public class WinlossReportFilterManager
    {
        #region Member Variables

        #region ColumnIndex
        //Row and Column Index of itemCollection array
        public const int All = 0;
        public const int SB = 1;
        public const int CS = 2;
        public const int HR = 3;
        public const int FI = 4;

        public const int NAME = 0;
        public const int TEXT = 1;
        public const int STATUS = 2;
        #endregion

        /// <summary>
        /// User doesn't have permission to view this checkbox
        /// </summary>
        public const String NOCHECK = "0";
        /// <summary>
        /// Uncheck
        /// </summary>
        public const String UNCHECK = "1";
        /// <summary>
        /// Check
        /// </summary>
        public const String CHECK = "2";

        public const string SHOWSB = "showsb";
        public const string SHOWCASINO = "showcasino";
        public const string SHOWP2P = "showp2p";
        public const string SHOWRB = "showrb";
        public const string SHOWFI = "showfi";
        public const string SHOWVIRTUALSPORTS = "showvs";

        private DateTime _dateFrom; // in comparison with Cross date
        private string[,] _itemCollection = null;
        private WinlossReportFilter_Control _control = null;
        private bool _isCheckedPermission = false;

        #endregion



        #region Constructors

        public WinlossReportFilterManager(string[,] _itemCollection, DateTime _dateFrom) : this(_itemCollection, true, _dateFrom) { }

        public WinlossReportFilterManager(string[,] itemCollection, bool isShowed, DateTime dateFrom)
        {
            this._itemCollection = itemCollection;
            _control = new WinlossReportFilter_Control(this._itemCollection, isShowed);
            this._dateFrom = dateFrom;
        }

        #endregion



        #region Process methods

        /// <summary>
        /// Render the control 
        /// </summary>
        /// <returns>string</returns>
        public string Render()
        {
            //Check permission and process request params
            if (!_isCheckedPermission)
            {
                CheckPermission();
            }

            return _control.ToString();
        }



        /// <summary>
        /// Get options (params) in filter
        /// </summary>
        /// <returns></returns>
        public string[] GetFilteredParams()
        {
            //Check permission and process request params
            if (!_isCheckedPermission)
            {
                CheckPermission();
            }

            int limit = _itemCollection.GetLength(1);
            bool[] temp = new bool[limit];
            string[] result = new string[limit];

            for (int col = 0; col < limit; col++) //ignore All item
            {
                temp[col] = (this._itemCollection[STATUS, col] == CHECK ? true : false);
            }

            if (this._itemCollection[STATUS, SB] == NOCHECK) // SB default value is Checked
            {
                temp[SB] = true;
            }

            for (int index = 0; index < limit; index++)
            {
                result[index] = (temp[index] == true ? "1" : "0");
            }

            return result;
        }

        /// <summary>
        /// Get options (params) in filter
        /// </summary>
        /// <param name="result"></param>
        public void GetFilteredParams(ref bool[] result)
        {
            //Check permission and process request params
            if (!_isCheckedPermission)
            {
                CheckPermission();
            }

            int limit = _itemCollection.GetLength(1);
            bool[] temp = new bool[limit];

            for (int col = 0; col < limit; col++) //ignore All item
            {
                temp[col] = (this._itemCollection[STATUS, col] == CHECK ? true : false);
            }

            if (this._itemCollection[STATUS, SB] == NOCHECK) // SB default value is Checked
            {
                temp[SB] = true;
            }

            result = temp;
        }

        public override string ToString()
        {
            return Render();
        }

        #endregion



        #region Helpers

        /// <summary>
        /// Check permission for Casino, HR and Finance
        /// </summary>
        private void CheckSpecificPermission()
        {
            CheckPermission(Sunplus.Agent.Model.Entities.Permission.UserPermission.IsShowCasino, CS, SHOWCASINO);

            CheckPermission(Sunplus.Agent.Model.Entities.Permission.UserPermission.IsShowRacing, HR, SHOWRB);
        }
        /// <summary>
        /// Check user permission on all items
        /// </summary>
        private void CheckPermission()
        {
            CheckSpecificPermission();
            //Check cross date
            CheckCrossDateConstraint();

            UpdateSportBookItem();

            UpdateItemAll();

            _isCheckedPermission = true;
        }
        /// <summary>
        /// Set nocheck status if user does not have permission 
        /// </summary>
        /// <param name="isAllowedPermission"></param>
        /// <param name="index"></param>
        /// <param name="paramName"></param>
        private void CheckPermission(bool isAllowedPermission, int index, string paramName)
        {
            if (isAllowedPermission)
            {
                this._itemCollection[STATUS, index] = GetCheckedParams(paramName) ? CHECK : UNCHECK;
            }
            else
            {
                this._itemCollection[STATUS, index] = NOCHECK;
            }
        }
        /// <summary>
        /// Update sport book item value
        /// </summary>
        private void UpdateSportBookItem()
        {
            bool noPermission = true;
            // Check if user have permission on any item
            for (int col = 1; col < _itemCollection.GetLength(1); col++)
            {
                if (this._itemCollection[STATUS, col] != NOCHECK)
                {
                    noPermission = false;
                    break;
                }
            }
            // If user have permission, set sportbook item as request param
            if (noPermission)
            {
                this._itemCollection[STATUS, SB] = NOCHECK;
            }
            else
            {
                this._itemCollection[STATUS, SB] = GetCheckedParams(SHOWSB) ? CHECK : UNCHECK;
            }
        }
        /// <summary>
        /// Update item all
        /// Item all will be showed when one of others was showed
        /// but it will not be showed when only one was showed.
        /// </summary>
        private void UpdateItemAll()
        {
            bool noPermission = true, isAll = true;

            // Check if user have permission on any item
            // Check if all item is check
            for (int col = 1, limit = _itemCollection.GetLength(1); col < limit; col++)
            {
                if (this._itemCollection[STATUS, col] != NOCHECK)
                {
                    noPermission = false;
                    if (this._itemCollection[STATUS, col] == UNCHECK)
                    {
                        isAll = false;
                    }
                }
            }

            // If user have permission on any item
            if (noPermission)
            {
                this._itemCollection[STATUS, All] = NOCHECK;
            }
            else
            {
                this._itemCollection[STATUS, All] = (isAll ? CHECK : UNCHECK);
            }
        }
        /// <summary>
        /// Return true if the param is null or is "1"
        /// </summary>
        /// <param name="paramName"></param>
        /// <returns></returns>
        private bool GetCheckedParams(string paramName)
        {
            string paramValue = HttpContext.Current.Request[paramName];

            if (string.IsNullOrEmpty(paramValue) || paramValue.Equals("1"))
            {
                return true;
            }
            return false;
        }
        /// <summary>
        /// Check cross date contrain
        /// </summary>
        private void CheckCrossDateConstraint()
        {
            DateTime boundDate = Sunplus.Agent.Model.BL.Definitions.AppSettings.SB_HR_FI_Date;
            bool isCross = false, isCheck = false;

            isCross = _dateFrom < boundDate;

            //Set constraint of SB, HR, FI if FromDate is before the boundDate
            if (isCross)
            {
                // Check if any item in SB, HR of FI is check
                for (int col = 0; col < this._itemCollection.GetLength(1); col++)
                {
                    if ((col == SB) || (col == HR) || (col == FI))
                    {
                        if (this._itemCollection[STATUS, col] == CHECK)
                        {
                            isCheck = true;
                            break;
                        }
                    }
                }
                // Check the item if user has permission
                if (isCheck)
                {
                    if (this._itemCollection[STATUS, SB] != NOCHECK)
                    {
                        this._itemCollection[STATUS, SB] = CHECK;
                    }
                    if (this._itemCollection[STATUS, HR] != NOCHECK)
                    {
                        this._itemCollection[STATUS, HR] = CHECK;
                    }
                    if (this._itemCollection[STATUS, FI] != NOCHECK)
                    {
                        this._itemCollection[STATUS, FI] = CHECK;
                    }
                }
            }
        }

        #endregion
    }
